-- Update 065: the country of each lead's phone number, for a flag beside
-- the number and a Country filter in All leads and Lead pipeline.
-- Apply after 064. Safe to rerun.
--
-- The country is worked out from the stored number when it is needed:
-- nothing is stored per lead and no number changes (owner decision,
-- 2026-11-13).
-- * crm_private.phone_country_rules: libphonenumber's rules, generated by
--   scripts/phone-country-rules.mjs. A calling code with one country gives
--   that country; a shared code (+1, +7, +44, …) tries its countries in the
--   library's order, by leading digits or by number patterns, so +1 416 is
--   Canada and +1 212 the United States.
-- * phone_country(number) and lead_phone_country(lead): the ISO country
--   code, or null when the number cannot be placed in one country (shown as
--   a globe, filtered as Unknown country).
-- * Checked edits: admin_lead_list, agent_lead_list and admin_agent_pipeline
--   take a country filter ('PK', 'AE', … or 'unknown'); admin_agent_pipeline
--   also returns the numbers of the leads it lists (temperatures), which the
--   page shows while a country is chosen.
begin;
set local lock_timeout='5s';
do $$ begin
 if not exists(select 1 from pg_constraint where conname='sheet_row_rejections_reason_check'
   and pg_get_constraintdef(oid) like '%phone_needs_country%')
  or to_regprocedure('public.admin_lead_list(uuid,jsonb)') is null
  or to_regprocedure('public.agent_lead_list(uuid,jsonb)') is null
  or to_regprocedure('public.admin_agent_pipeline(uuid,uuid,jsonb)') is null then
  raise exception 'Apply CRM updates up to 064 before update 065.';
 end if;
end $$;

-- ------------------------------------------------------- the rules
create table if not exists crm_private.phone_country_rules(
 calling_code text not null check(calling_code ~ '^[1-9][0-9]{0,2}$'),
 position integer not null check(position>0),
 country text not null check(country ~ '^[A-Z]{2}$'),
 leading_digits text,
 number_pattern text,
 type_pattern text,
 primary key(calling_code,position));
revoke all on crm_private.phone_country_rules from public,anon,authenticated;
-- Reference data, replaced whole: libphonenumber-js 1.13.15's rules.
delete from crm_private.phone_country_rules;
insert into crm_private.phone_country_rules(calling_code,position,country,leading_digits,number_pattern,type_pattern) values
