-- ------------------------------------------------------- the country
-- The ISO country of a number in +E.164, as libphonenumber decides it
-- (parsePhoneNumber(number).country), or null.
create or replace function public.phone_country(p_phone text) returns text
language plpgsql stable security definer set search_path='' as $$
declare d text;v_code text;national text;r crm_private.phone_country_rules;
begin
 if p_phone is null or p_phone !~ '^\+[1-9][0-9]{6,14}$' then return null;end if;
 d=substr(p_phone,2);
 -- Calling codes are one to three digits, and none begins another.
 select x.calling_code into v_code from crm_private.phone_country_rules x
  where x.calling_code in (left(d,1),left(d,2),left(d,3)) limit 1;
 if v_code is null then return null;end if;
 national=substr(d,length(v_code)+1);
 for r in select * from crm_private.phone_country_rules x where x.calling_code=v_code order by x.position loop
  if r.leading_digits is null and r.number_pattern is null then return r.country;
  elsif r.leading_digits is not null then
   if national ~ ('^(?:'||r.leading_digits||')') then return r.country;end if;
  elsif r.type_pattern is not null and national ~ ('^(?:'||r.number_pattern||')$')
   and national ~ ('^(?:'||r.type_pattern||')$') then
   return r.country;
  end if;
 end loop;
 return null;
end $$;

create or replace function public.lead_phone_country(p_lead uuid) returns text
language sql stable security definer set search_path='' as $$
 select public.phone_country(p.phone) from crm_private.lead_phones p where p.lead_id=p_lead
$$;

-- ------------------------------------------------------- the filters
-- Small, checked edits, as in updates 061, 063 and 064: each text must
-- appear exactly once, or the update stops and changes nothing. On a rerun
-- the edited text is found and left alone.
do $patch$
declare item record;body text;n integer;
begin
 for item in select * from (values
  -- All leads (update 057).
  ('public.admin_lead_list(uuid,jsonb)',
   $t$where e.key not in ('search','assignment','agent','call','status','lost_reason','temperature','outcome','source','import','page','ids')$t$,
   $t$where e.key not in ('search','assignment','agent','call','status','lost_reason','temperature','outcome','source','import','page','ids','country')$t$),
  ('public.admin_lead_list(uuid,jsonb)',
   $t$or (v_assignment is not null and v_assignment not in ('assigned','unassigned'))$t$,
   $t$or coalesce(q->>'country','unknown')!~'^([A-Z]{2}|unknown)$' or (v_assignment is not null and v_assignment not in ('assigned','unassigned'))$t$),
  ('public.admin_lead_list(uuid,jsonb)',
   $t$and (v_status is null or l.status=v_status)$t$,
   $t$and (v_status is null or l.status=v_status)
   and (q->>'country' is null or coalesce(public.lead_phone_country(l.id),'unknown')=q->>'country')$t$),
  -- An agent's Assigned leads and Lead pipeline (updates 052, 053, 061).
  ('public.agent_lead_list(uuid,jsonb)',
   $t$where e.key not in ('view','import','search','status','temperature','source','call','outcome','assignment','sort','page')$t$,
   $t$where e.key not in ('view','import','search','status','temperature','source','call','outcome','assignment','sort','page','country')$t$),
  ('public.agent_lead_list(uuid,jsonb)',
   $t$or (v_assignment is not null and v_assignment<>'reassigned')$t$,
   $t$or coalesce(q->>'country','unknown')!~'^([A-Z]{2}|unknown)$' or (v_assignment is not null and v_assignment<>'reassigned')$t$),
  ('public.agent_lead_list(uuid,jsonb)',
   $t$and (v_status is null or m.ws_status=v_status)$t$,
   $t$and (v_status is null or m.ws_status=v_status)
   and (q->>'country' is null or coalesce(public.lead_phone_country(m.id),'unknown')=q->>'country')$t$),
  -- An agent's pipeline as administrators see it (update 055).
  ('public.admin_agent_pipeline(uuid,uuid,jsonb)',
   $t$where e.key not in ('view','search','temperature','outcome','page')$t$,
   $t$where e.key not in ('view','search','temperature','outcome','page','country')$t$),
  ('public.admin_agent_pipeline(uuid,uuid,jsonb)',
   $t$or (v_temperature is not null and v_temperature not in ('hot','warm','cold','none'))$t$,
   $t$or coalesce(q->>'country','unknown')!~'^([A-Z]{2}|unknown)$' or (v_temperature is not null and v_temperature not in ('hot','warm','cold','none'))$t$),
  ('public.admin_agent_pipeline(uuid,uuid,jsonb)',
   $t$and (v_outcome is null or sp.last_call_outcome=v_outcome)$t$,
   $t$and (v_outcome is null or sp.last_call_outcome=v_outcome)
   and (q->>'country' is null or coalesce(public.lead_phone_country(sp.id),'unknown')=q->>'country')$t$),
  ('public.admin_agent_pipeline(uuid,uuid,jsonb)',
   $t$'count',(select count(*) from hits),$t$,
   $t$'count',(select count(*) from hits),
  -- The numbers of the leads listed (search, outcome and country).
  'temperatures',(select jsonb_build_object('contacted',count(*),'hot',count(*) filter (where temperature='hot'),
   'warm',count(*) filter (where temperature='warm'),'cold',count(*) filter (where temperature='cold'),
   'none',count(*) filter (where temperature is null)) from matched),$t$)
 ) v(signature,old_text,new_text) loop
  body=pg_get_functiondef(item.signature::regprocedure);
  if position(item.new_text in body)>0 then continue;end if;
  n=(length(body)-length(replace(body,item.old_text,'')))/length(item.old_text);
  if n<>1 then
   raise exception 'Update 065 found an unexpected version of %: apply CRM updates up to 064 exactly.',item.signature;
  end if;
  execute replace(body,item.old_text,item.new_text);
 end loop;
end $patch$;

-- ------------------------------------------------------- access
-- Helpers for the list functions only; browsers and the API reach neither.
revoke all on function public.phone_country(text) from public,anon,authenticated,service_role;
revoke all on function public.lead_phone_country(uuid) from public,anon,authenticated,service_role;
commit;
